'use client';

import { useEffect, useId, useRef, useState } from 'react';
import './expanding-search-field.css';

export interface ExpandingSearchFieldProps {
  value: string;
  onValueChange: (value: string) => void;
  /** Accessible name, for example "Search harbors". */
  label: string;
  placeholder?: string;
  /** Id of the results the input filters, for aria-controls. */
  controls?: string;
  className?: string;
}

/**
 * A compact search button that grows into a field. Its right edge stays
 * anchored. The input takes focus on open; Escape clears and closes it and
 * puts focus back on the button.
 */
export function ExpandingSearchField({
  value,
  onValueChange,
  label,
  placeholder = 'Search',
  controls,
  className = '',
}: ExpandingSearchFieldProps) {
  const [open, setOpen] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  const toggle = useRef<HTMLButtonElement>(null);
  const reopened = useRef(false);
  const id = useId();

  useEffect(() => {
    if (open) input.current?.focus();
    else if (reopened.current) toggle.current?.focus();
  }, [open]);

  const close = () => {
    reopened.current = true;
    onValueChange('');
    setOpen(false);
  };

  return (
    <div className={`mg-search ${className}`} data-open={open} role='search'>
      <label htmlFor={id} className='mg-search__sr'>
        {label}
      </label>
      <input
        ref={input}
        id={id}
        type='search'
        className='mg-search__input'
        placeholder={placeholder}
        value={value}
        tabIndex={open ? 0 : -1}
        aria-hidden={!open}
        aria-controls={controls}
        onChange={(event) => onValueChange(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === 'Escape') {
            event.preventDefault();
            close();
          }
        }}
      />
      <button
        ref={toggle}
        type='button'
        className='mg-search__toggle'
        aria-label={open ? `Close ${label.toLowerCase()}` : label}
        aria-expanded={open}
        onClick={() => (open ? close() : setOpen(true))}
      >
        <svg viewBox='0 0 20 20' aria-hidden='true'>
          <circle className='mg-search__lens' cx='8.5' cy='8.5' r='5' />
          <path className='mg-search__lens' d='M12.5 12.5 L16.5 16.5' />
          <path className='mg-search__x' d='M5 5 L15 15 M15 5 L5 15' />
        </svg>
      </button>
    </div>
  );
}

.mg-search {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  width: 44px;
  height: 44px;
  margin-left: auto;
  border: 1px solid var(--mg-line-strong, #b9c5e6);
  border-radius: 999px;
  background: #fff;
  transition: width 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-search[data-open='true'] {
  width: 100%;
  border-color: var(--mg-accent, #164cff);
}

.mg-search:focus-within {
  box-shadow: 0 0 0 3px #e6ecff;
}

.mg-search__input {
  flex: 1;
  min-width: 0;
  height: 100%;
  padding: 0 0 0 16px;
  border: 0;
  background: none;
  color: var(--mg-ink, #0c1738);
  font: inherit;
  opacity: 0;
  transition: opacity 160ms ease;
}

.mg-search[data-open='true'] .mg-search__input {
  opacity: 1;
  transition-delay: 120ms;
}

.mg-search__input:focus {
  outline: none;
}

.mg-search__toggle {
  display: grid;
  flex: none;
  place-items: center;
  width: 42px;
  height: 42px;
  border: 0;
  border-radius: 50%;
  background: none;
  color: var(--mg-ink, #0c1738);
  cursor: pointer;
}

.mg-search__toggle:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: 1px;
}

.mg-search__toggle svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
}

.mg-search__lens,
.mg-search__x {
  transition: opacity 200ms ease;
}

.mg-search__x {
  opacity: 0;
}

.mg-search[data-open='true'] .mg-search__lens {
  opacity: 0;
}

.mg-search[data-open='true'] .mg-search__x {
  opacity: 1;
}

.mg-search__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

@media (prefers-reduced-motion: reduce) {
  .mg-search,
  .mg-search__input,
  .mg-search__lens,
  .mg-search__x {
    transition: none;
  }
}
